@Test
public void testUploadMetricsFlow() throws InterruptedException {
    long startTime = System.currentTimeMillis();
    // This test verifies the flow of metrics emitted during a segment upload to deep store.
    ResourceUtils.emitPreSegmentUploadMetrics(_metrics, RAW_TABLE, SEGMENT_BYTES);
    verify(_metrics).setOrUpdateTableGauge(RAW_TABLE, ControllerGauge.DEEP_STORE_WRITE_OPS_IN_PROGRESS, 1L);
    verify(_metrics).setOrUpdateTableGauge(RAW_TABLE, ControllerGauge.DEEP_STORE_WRITE_BYTES_IN_PROGRESS, SEGMENT_BYTES);
    // Simulate upload latency
    long simulatedDelay = 50L;
    Thread.sleep(simulatedDelay);
    // Post-upload metrics
    ResourceUtils.emitPostSegmentUploadMetrics(_metrics, RAW_TABLE, startTime, SEGMENT_BYTES);
    // ops / bytes gauges should be back to zero
    verify(_metrics, atLeastOnce()).setOrUpdateTableGauge(RAW_TABLE, ControllerGauge.DEEP_STORE_WRITE_OPS_IN_PROGRESS, 0L);
    verify(_metrics, atLeastOnce()).setValueOfGlobalGauge(ControllerGauge.DEEP_STORE_WRITE_OPS_IN_PROGRESS, 0L);
    verify(_metrics, atLeastOnce()).setOrUpdateTableGauge(RAW_TABLE, ControllerGauge.DEEP_STORE_WRITE_BYTES_IN_PROGRESS, 0L);
    verify(_metrics, atLeastOnce()).setValueOfGlobalGauge(ControllerGauge.DEEP_STORE_WRITE_BYTES_IN_PROGRESS, 0L);
    // timers & meters fire once
    verify(_metrics).addTimedTableValue(eq(RAW_TABLE), eq(ControllerTimer.DEEP_STORE_SEGMENT_WRITE_TIME_MS), anyLong(), eq(TimeUnit.MILLISECONDS));
    verify(_metrics).addMeteredTableValue(RAW_TABLE, ControllerMeter.DEEP_STORE_WRITE_BYTES_COMPLETED, SEGMENT_BYTES);
    //  ArgumentCaptor to capture the long duration value that gets passed into the addTimedTableValue(...) method.
    //  This allows the test to inspect the actual argument used when the metric was recorded.
    ArgumentCaptor<Long> durationCaptor = ArgumentCaptor.forClass(Long.class);
    verify(_metrics).addTimedTableValue(eq(RAW_TABLE), eq(ControllerTimer.DEEP_STORE_SEGMENT_WRITE_TIME_MS), durationCaptor.capture(), eq(TimeUnit.MILLISECONDS));
    assertTrue(durationCaptor.getValue() >= simulatedDelay, "Expected write latency >= " + simulatedDelay + "ms but got " + durationCaptor.getValue());
}

