    when(segmentManager._mockedFileUploadDownloadClient.uploadToSegmentStore(serverUploadRequestUrl1)).thenThrow(new HttpErrorStatusException("failed to upload segment", Response.Status.INTERNAL_SERVER_ERROR.getStatusCode()));
