    // Verify later the download url is still the same.
    String defaultDownloadUrl = "canItBeDownloaded";
    segmentsZKMetadata.get(3).setStatus(Status.DONE);
    segmentsZKMetadata.get(3).setDownloadUrl(defaultDownloadUrl);
    // Keep 5th segment status as IN_PROGRESS.
    List<String> segmentNames = segmentsZKMetadata.stream().map(SegmentZKMetadata::getSegmentName).collect(Collectors.toList());
    when(pinotHelixResourceManager.getTableConfig(REALTIME_TABLE_NAME)).thenReturn(segmentManager._tableConfig);
    // Verify the result
    segmentManager.uploadToDeepStoreIfMissing(segmentManager._tableConfig, segmentsZKMetadata);
    // Block until all tasks have been able to complete
    TestUtils.waitForCondition(aVoid -> segmentManager.deepStoreUploadExecutorPendingSegmentsIsEmpty(), 30_000L, "Timed out waiting for upload retry tasks to finish");
    assertEquals(segmentManager.getSegmentZKMetadata(REALTIME_TABLE_NAME, segmentNames.get(0), null).getDownloadUrl(), expectedSegmentLocation);
    assertFalse(tempSegmentFileLocation.exists(), "Deep-store retry task should move the file from temp location to permanent location");
    assertEquals(segmentManager.getSegmentZKMetadata(REALTIME_TABLE_NAME, segmentNames.get(1), null).getDownloadUrl(), METADATA_URI_FOR_PEER_DOWNLOAD);
    assertEquals(segmentManager.getSegmentZKMetadata(REALTIME_TABLE_NAME, segmentNames.get(2), null).getDownloadUrl(), METADATA_URI_FOR_PEER_DOWNLOAD);
    assertEquals(segmentManager.getSegmentZKMetadata(REALTIME_TABLE_NAME, segmentNames.get(3), null).getDownloadUrl(), defaultDownloadUrl);
    assertNull(segmentManager.getSegmentZKMetadata(REALTIME_TABLE_NAME, segmentNames.get(4), null).getDownloadUrl());
}

