@Test
public void testGetPartitionIds() throws Exception {
    List<StreamConfig> streamConfigs = List.of(FakeStreamConfigUtils.getDefaultLowLevelStreamConfigs());
    IdealState idealState = new IdealState(REALTIME_TABLE_NAME);
    FakePinotLLCRealtimeSegmentManager segmentManager = new FakePinotLLCRealtimeSegmentManager();
    segmentManager._numPartitions = 2;
    // Test empty ideal state
    Set<Integer> partitionIds = segmentManager.getPartitionIds(streamConfigs, idealState);
    Assert.assertEquals(partitionIds.size(), 2);
    partitionIds.clear();
    // Simulate the case where getPartitionIds(StreamConfig) throws an exception (e.g. transient kafka connection issue)
    PinotLLCRealtimeSegmentManager segmentManagerSpy = spy(FakePinotLLCRealtimeSegmentManager.class);
    doThrow(new RuntimeException()).when(segmentManagerSpy).getPartitionIds(any(StreamConfig.class));
    List<PartitionGroupConsumptionStatus> partitionGroupConsumptionStatusList = List.of(new PartitionGroupConsumptionStatus(0, 12, new LongMsgOffset(123), new LongMsgOffset(234), "ONLINE"), new PartitionGroupConsumptionStatus(1, 12, new LongMsgOffset(123), new LongMsgOffset(345), "ONLINE"));
    doReturn(partitionGroupConsumptionStatusList).when(segmentManagerSpy).getPartitionGroupConsumptionStatusList(idealState, streamConfigs);
    List<PartitionGroupMetadata> partitionGroupMetadataList = List.of(new PartitionGroupMetadata(0, new LongMsgOffset(234)), new PartitionGroupMetadata(1, new LongMsgOffset(345)));
    doReturn(partitionGroupMetadataList).when(segmentManagerSpy).getNewPartitionGroupMetadataList(streamConfigs, partitionGroupConsumptionStatusList, idealState);
    partitionIds = segmentManagerSpy.getPartitionIds(streamConfigs, idealState);
    Assert.assertEquals(partitionIds.size(), 2);
}

