@Test
public void testReduceSegmentSizeAndReset() {
    // Set up a new table with 2 replicas, 5 instances, 4 partitions
    PinotHelixResourceManager mockHelixResourceManager = mock(PinotHelixResourceManager.class);
    FakePinotLLCRealtimeSegmentManager segmentManager = new FakePinotLLCRealtimeSegmentManager(mockHelixResourceManager);
    setUpNewTable(segmentManager, 2, 5, 5);
    SegmentsValidationAndRetentionConfig segmentsValidationAndRetentionConfig = new SegmentsValidationAndRetentionConfig();
    segmentsValidationAndRetentionConfig.setRetentionTimeUnit(TimeUnit.DAYS.toString());
    segmentsValidationAndRetentionConfig.setRetentionTimeValue("3");
    segmentManager._tableConfig.setValidationConfig(segmentsValidationAndRetentionConfig);
    String segmentName = new ArrayList<>(segmentManager._segmentZKMetadataMap.keySet()).get(0);
    SegmentZKMetadata segmentZKMetadata = segmentManager.getSegmentZKMetadata(REALTIME_TABLE_NAME, segmentName, null);
    int prevRowSize = segmentZKMetadata.getSizeThresholdToFlushSegment();
    segmentManager.reduceSegmentSizeAndReset(new LLCSegmentName(segmentName), 100);
    Assert.assertEquals(Math.min(100 / 2, prevRowSize / 2), segmentManager.getSegmentZKMetadata(REALTIME_TABLE_NAME, segmentName, null).getSizeThresholdToFlushSegment());
}

@Test
public void testGetInstanceToConsumingSegments() {
    PinotHelixResourceManager mockHelixResourceManager = mock(PinotHelixResourceManager.class);
    FakePinotLLCRealtimeSegmentManager realtimeSegmentManager = new FakePinotLLCRealtimeSegmentManager(mockHelixResourceManager);
    IdealState idealState = mock(IdealState.class);
    Map<String, Map<String, String>> map = Map.of("seg0", Map.of("i1", "CONSUMING", "i4", "ONLINE"), "seg1", Map.of("i2", "CONSUMING"), "seg2", Map.of("i3", "CONSUMING", "i2", "OFFLINE"), "seg3", Map.of("i4", "CONSUMING", "i2", "CONSUMING", "i3", "CONSUMING"), "seg4", Map.of("i5", "CONSUMING", "i1", "CONSUMING", "i3", "CONSUMING"));
    ZNRecord znRecord = mock(ZNRecord.class);
    when(znRecord.getMapFields()).thenReturn(map);
    when(idealState.getRecord()).thenReturn(znRecord);
    // Use TreeSet to ensure ordering
    Set<String> targetConsumingSegment = new TreeSet<>(map.keySet());
    Map<String, Queue<String>> instanceToConsumingSegments = realtimeSegmentManager.getInstanceToConsumingSegments(idealState, targetConsumingSegment);
    assertEquals(instanceToConsumingSegments, Map.of("i1", new LinkedList<>(List.of("seg0", "seg4")), "i2", new LinkedList<>(List.of("seg1", "seg3")), "i3", new LinkedList<>(List.of("seg2", "seg3", "seg4")), "i4", new LinkedList<>(List.of("seg3")), "i5", new LinkedList<>(List.of("seg4"))));
}

