    when(tableRebalanceManager.rebalanceTableAsync(anyString(), any(TableConfig.class), anyString(), any(RebalanceConfig.class), any(ZkBasedTableRebalanceObserver.class))).thenReturn(CompletableFuture.completedFuture(null));
    RebalanceChecker checker = new RebalanceChecker(tableRebalanceManager, helixManager, leadController, cfg, metrics);
    checker.retryRebalanceTable(tableName, allJobMetadata);
    // Retry for job1 is delayed with 5min backoff.
    ArgumentCaptor<ZkBasedTableRebalanceObserver> observerCaptor = ArgumentCaptor.forClass(ZkBasedTableRebalanceObserver.class);
    verify(tableRebalanceManager, never()).rebalanceTable(eq(tableName), any(), anyString(), any(), observerCaptor.capture());
    // Set initial delay to 0 to disable retry backoff.
    jobCfg.setRetryInitialDelayInMs(0);
    jobMetadata = ZkBasedTableRebalanceObserver.createJobMetadata(tableName, "job1", stats, jobCtx);
    allJobMetadata.put("job1", jobMetadata);
    checker.retryRebalanceTable(tableName, allJobMetadata);
    // Retry for job1 is delayed with 0 backoff.
    observerCaptor = ArgumentCaptor.forClass(ZkBasedTableRebalanceObserver.class);
    verify(tableRebalanceManager, times(1)).rebalanceTableAsync(eq(tableName), any(), anyString(), any(), observerCaptor.capture());
}

