public void testControllerJobZkMetadataExpiryWithInProgressJobs() throws Exception {
    // Setup job limits
    ControllerConf controllerConf = mock(ControllerConf.class);
    when(controllerConf.getMaxTableRebalanceZkJobs()).thenReturn(2);
    ControllerJobTypes.init(controllerConf);
    TableRebalanceProgressStats inProgressStats = new TableRebalanceProgressStats();
    inProgressStats.setStatus(RebalanceResult.Status.IN_PROGRESS);
    TableRebalanceProgressStats completedStats = new TableRebalanceProgressStats();
    completedStats.setStatus(RebalanceResult.Status.DONE);
    TableRebalanceProgressStats abortedStats = new TableRebalanceProgressStats();
    abortedStats.setStatus(RebalanceResult.Status.ABORTED);
    Map<String, Map<String, String>> jobMetadataMap = Map.of("job1", Map.of(CommonConstants.ControllerJob.SUBMISSION_TIME_MS, "1000", CommonConstants.ControllerJob.JOB_TYPE, ControllerJobTypes.TABLE_REBALANCE.name(), RebalanceJobConstants.JOB_METADATA_KEY_REBALANCE_PROGRESS_STATS, JsonUtils.objectToString(inProgressStats)), "job2", Map.of(CommonConstants.ControllerJob.SUBMISSION_TIME_MS, "3000", CommonConstants.ControllerJob.JOB_TYPE, ControllerJobTypes.TABLE_REBALANCE.name(), RebalanceJobConstants.JOB_METADATA_KEY_REBALANCE_PROGRESS_STATS, JsonUtils.objectToString(completedStats)), "job3", Map.of(CommonConstants.ControllerJob.SUBMISSION_TIME_MS, "2000", CommonConstants.ControllerJob.JOB_TYPE, ControllerJobTypes.TABLE_REBALANCE.name(), RebalanceJobConstants.JOB_METADATA_KEY_REBALANCE_PROGRESS_STATS, JsonUtils.objectToString(abortedStats)), "job4", Map.of(CommonConstants.ControllerJob.SUBMISSION_TIME_MS, "4000", CommonConstants.ControllerJob.JOB_TYPE, ControllerJobTypes.TABLE_REBALANCE.name(), RebalanceJobConstants.JOB_METADATA_KEY_REBALANCE_PROGRESS_STATS, JsonUtils.objectToString(inProgressStats)), "job5", Map.of(CommonConstants.ControllerJob.SUBMISSION_TIME_MS, "5000", CommonConstants.ControllerJob.JOB_TYPE, ControllerJobTypes.TABLE_REBALANCE.name(), RebalanceJobConstants.JOB_METADATA_KEY_REBALANCE_PROGRESS_STATS, JsonUtils.objectToString(inProgressStats)));
    Map<String, Map<String, String>> updatedJobMetadataMap = ControllerZkHelixUtils.expireControllerJobsInZk(jobMetadataMap, ControllerJobTypes.TABLE_REBALANCE);
    // Even though the limit is 2, we should not delete the in-progress jobs
    assertEquals(updatedJobMetadataMap.size(), 3);
    assertEquals(updatedJobMetadataMap.keySet(), Set.of("job1", "job4", "job5"));
}

