        when(leadControllerManager.isLeaderForTable(anyString())).thenReturn(true);
    }
    PinotMetricsRegistry metricsRegistry = PinotMetricUtils.getPinotMetricsRegistry();
    ControllerMetrics controllerMetrics = new ControllerMetrics(metricsRegistry);
    // server 1 caught up on partition-1 and partition-2
    // server 2 lags for partition-2 and caught up on partition-1
    // So, the consumer monitor should show: 1. partition-1 has 0 lag; partition-2 has some non-zero lag.
    // Segment 1 in replicas:
    TreeMap<String, List<ConsumingSegmentInfoReader.ConsumingSegmentInfo>> response = new TreeMap<>();
    List<ConsumingSegmentInfoReader.ConsumingSegmentInfo> part1ServerConsumingSegmentInfo = List.of(getConsumingSegmentInfoForServer("pinot1", "1", "100", "100", "0"), getConsumingSegmentInfoForServer("pinot2", "1", "100", "100", "0"));
    response.put(segmentPartition1Seq1.getSegmentName(), part1ServerConsumingSegmentInfo);
    // Segment 2 in replicas
    List<ConsumingSegmentInfoReader.ConsumingSegmentInfo> part2ServerConsumingSegmentInfo = List.of(getConsumingSegmentInfoForServer("pinot1", "2", "120", "120", "0"), getConsumingSegmentInfoForServer("pinot2", "2", "80", "120", "60000"));
    response.put(segmentPartition2Seq0.getSegmentName(), part2ServerConsumingSegmentInfo);
    ConsumingSegmentInfoReader consumingSegmentReader = mock(ConsumingSegmentInfoReader.class);
    when(consumingSegmentReader.getConsumingSegmentsInfo(realtimeTableName, 10000)).thenReturn(new ConsumingSegmentInfoReader.ConsumingSegmentsInfoMap(response, 0, 0));
    RealtimeConsumerMonitor realtimeConsumerMonitor = new RealtimeConsumerMonitor(config, helixResourceManager, leadControllerManager, controllerMetrics, consumingSegmentReader);
    realtimeConsumerMonitor.start();
    realtimeConsumerMonitor.run();
    assertEquals(MetricValueUtils.getPartitionGaugeValue(controllerMetrics, realtimeTableName, 1, ControllerGauge.MAX_RECORDS_LAG), 0);
    assertEquals(MetricValueUtils.getPartitionGaugeValue(controllerMetrics, realtimeTableName, 2, ControllerGauge.MAX_RECORDS_LAG), 40);
    assertEquals(MetricValueUtils.getPartitionGaugeValue(controllerMetrics, realtimeTableName, 1, ControllerGauge.MAX_RECORD_AVAILABILITY_LAG_MS), 0);
    assertEquals(MetricValueUtils.getPartitionGaugeValue(controllerMetrics, realtimeTableName, 2, ControllerGauge.MAX_RECORD_AVAILABILITY_LAG_MS), 60000);
}

