    Map<String, String> segmentGenerationAndPushTaskConfig = ImmutableMap.of("schedule", "0 */10 * ? * * *");
    TableConfig tableConfig = new TableConfigBuilder(TableType.OFFLINE).setTableName(RAW_TABLE_NAME).setTaskConfig(new TableTaskConfig(ImmutableMap.of("RealtimeToOfflineSegmentsTask", realtimeToOfflineTaskConfig, "SegmentGenerationAndPushTask", segmentGenerationAndPushTaskConfig))).build();
    // validate valid config
    taskGenerator.validateTaskConfigs(tableConfig, schema, realtimeToOfflineTaskConfig);
    // invalid Upsert config with RealtimeToOfflineTask
    tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(RAW_TABLE_NAME).setTimeColumnName(TIME_COLUMN_NAME).setUpsertConfig(new UpsertConfig(UpsertConfig.Mode.FULL)).setTaskConfig(new TableTaskConfig(ImmutableMap.of("RealtimeToOfflineSegmentsTask", realtimeToOfflineTaskConfig, "SegmentGenerationAndPushTask", segmentGenerationAndPushTaskConfig))).build();
    try {
        taskGenerator.validateTaskConfigs(tableConfig, schema, realtimeToOfflineTaskConfig);
        Assert.fail();
    } catch (IllegalStateException e) {
        Assert.assertTrue(e.getMessage().contains("RealtimeToOfflineTask doesn't support upsert table"));
    }
    // invalid period
    HashMap<String, String> invalidPeriodConfig = new HashMap<>(realtimeToOfflineTaskConfig);
    invalidPeriodConfig.put("roundBucketTimePeriod", "garbage");
    tableConfig = new TableConfigBuilder(TableType.OFFLINE).setTableName(RAW_TABLE_NAME).setTaskConfig(new TableTaskConfig(ImmutableMap.of("RealtimeToOfflineSegmentsTask", invalidPeriodConfig, "SegmentGenerationAndPushTask", segmentGenerationAndPushTaskConfig))).build();
    try {
        taskGenerator.validateTaskConfigs(tableConfig, schema, invalidPeriodConfig);
        Assert.fail();
    } catch (IllegalArgumentException e) {
        Assert.assertTrue(e.getMessage().contains("Invalid time spec"));
    }
    // invalid mergeType
    HashMap<String, String> invalidMergeType = new HashMap<>(realtimeToOfflineTaskConfig);
    invalidMergeType.put("mergeType", "garbage");
    tableConfig = new TableConfigBuilder(TableType.OFFLINE).setTableName(RAW_TABLE_NAME).setTaskConfig(new TableTaskConfig(ImmutableMap.of("RealtimeToOfflineSegmentsTask", invalidMergeType, "SegmentGenerationAndPushTask", segmentGenerationAndPushTaskConfig))).build();
    try {
        taskGenerator.validateTaskConfigs(tableConfig, schema, invalidMergeType);
        Assert.fail();
    } catch (IllegalStateException e) {
        Assert.assertTrue(e.getMessage().contains("MergeType must be one of"));
    }
    // invalid column
    HashMap<String, String> invalidColumnConfig = new HashMap<>(realtimeToOfflineTaskConfig);
    invalidColumnConfig.put("score.aggregationType", "max");
    tableConfig = new TableConfigBuilder(TableType.OFFLINE).setTableName(RAW_TABLE_NAME).setTaskConfig(new TableTaskConfig(ImmutableMap.of("RealtimeToOfflineSegmentsTask", invalidColumnConfig, "SegmentGenerationAndPushTask", segmentGenerationAndPushTaskConfig))).build();
    try {
        taskGenerator.validateTaskConfigs(tableConfig, schema, invalidColumnConfig);
        Assert.fail();
    } catch (IllegalStateException e) {
        Assert.assertTrue(e.getMessage().contains("not found in schema"));
    }
    // invalid agg
    HashMap<String, String> invalidAggConfig = new HashMap<>(realtimeToOfflineTaskConfig);
    invalidAggConfig.put("myCol.aggregationType", "garbage");
    tableConfig = new TableConfigBuilder(TableType.OFFLINE).setTableName(RAW_TABLE_NAME).setTaskConfig(new TableTaskConfig(ImmutableMap.of("RealtimeToOfflineSegmentsTask", invalidAggConfig, "SegmentGenerationAndPushTask", segmentGenerationAndPushTaskConfig))).build();
    try {
        taskGenerator.validateTaskConfigs(tableConfig, schema, invalidAggConfig);
        Assert.fail();
    } catch (IllegalStateException e) {
        Assert.assertTrue(e.getMessage().contains("has invalid aggregate type"));
    }
    // aggregation function that exists but has no ValueAggregator available
    HashMap<String, String> invalidAgg2Config = new HashMap<>(realtimeToOfflineTaskConfig);
    invalidAgg2Config.put("myCol.aggregationType", "Histogram");
    tableConfig = new TableConfigBuilder(TableType.OFFLINE).setTableName(RAW_TABLE_NAME).setTaskConfig(new TableTaskConfig(ImmutableMap.of("RealtimeToOfflineSegmentsTask", invalidAgg2Config, "SegmentGenerationAndPushTask", segmentGenerationAndPushTaskConfig))).build();
    try {
        taskGenerator.validateTaskConfigs(tableConfig, schema, invalidAgg2Config);
        Assert.fail();
    } catch (IllegalStateException e) {
        Assert.assertTrue(e.getMessage().contains("has invalid aggregate type"));
    }
    // valid agg
    HashMap<String, String> validAggConfig = new HashMap<>(realtimeToOfflineTaskConfig);
    validAggConfig.put("myCol.aggregationType", "distinctCountHLL");
    tableConfig = new TableConfigBuilder(TableType.OFFLINE).setTableName(RAW_TABLE_NAME).setTaskConfig(new TableTaskConfig(ImmutableMap.of("RealtimeToOfflineSegmentsTask", validAggConfig, "SegmentGenerationAndPushTask", segmentGenerationAndPushTaskConfig))).build();
    taskGenerator.validateTaskConfigs(tableConfig, schema, validAggConfig);
    // valid agg
    HashMap<String, String> validAgg2Config = new HashMap<>(realtimeToOfflineTaskConfig);
    validAgg2Config.put("myCol.aggregationType", "distinctCountHLLPlus");
    tableConfig = new TableConfigBuilder(TableType.OFFLINE).setTableName(RAW_TABLE_NAME).setTaskConfig(new TableTaskConfig(ImmutableMap.of("RealtimeToOfflineSegmentsTask", validAgg2Config, "SegmentGenerationAndPushTask", segmentGenerationAndPushTaskConfig))).build();
