@Test
public void shouldHandleHashJoinKeyCollisionLeftJoinWithNulls() {
    // Test LEFT join with both hash collision AND null values
    _leftInput = new BlockListMultiStageOperator.Builder(DEFAULT_CHILD_SCHEMA).addRow(1, // Hash collision string
    "Aa").addRow(2, // Hash collision string
    "BB").addRow(3, // Null key
    null).addRow(4, // Non-collision string
    "CC").buildWithEos();
    _rightInput = new BlockListMultiStageOperator.Builder(DEFAULT_CHILD_SCHEMA).addRow(2, // Hash collision match
    "Aa").addRow(2, // Hash collision match
    "BB").addRow(3, // Null key - should NOT match left null
    null).addRow(5, // No match in left
    "DD").buildWithEos();
    DataSchema resultSchema = new DataSchema(new String[] { "int_col1", "string_col1", "int_col2", "string_col2" }, new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.STRING, ColumnDataType.INT, ColumnDataType.STRING });
    HashJoinOperator operator = getOperator(resultSchema, JoinRelType.LEFT, List.of(1), List.of(1), List.of());
    List<Object[]> resultRows = ((MseBlock.Data) operator.nextBlock()).asRowHeap().getRows();
    assertEquals(resultRows.size(), 4);
    // Hash collision match
    assertEquals(resultRows.get(0), new Object[] { 1, "Aa", 2, "Aa" });
    // Hash collision match
    assertEquals(resultRows.get(1), new Object[] { 2, "BB", 2, "BB" });
    // Left null preserved, no match
    assertEquals(resultRows.get(2), new Object[] { 3, null, null, null });
    // Left unmatched preserved
    assertEquals(resultRows.get(3), new Object[] { 4, "CC", null, null });
}

