@Test
public void shouldHandleCompositeKeyWithNullValues() {
    // Test composite key join (multi-column) with null values
    // This should expose the bug in isNullKey method where it checks for Object[] instead of Key
    DataSchema compositeSchema = new DataSchema(new String[] { "int_col", "string_col", "double_col" }, new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.STRING, ColumnDataType.DOUBLE });
    _leftInput = new BlockListMultiStageOperator.Builder(compositeSchema).addRow(1, "Aa", // Normal row
    1.0).addRow(2, null, // Null in second key component
    2.0).addRow(3, "Cc", // Null in third key component
    null).addRow(4, "Dd", // Normal row
    4.0).buildWithEos();
    _rightInput = new BlockListMultiStageOperator.Builder(compositeSchema).addRow(1, "Aa", // Match for first left row
    1.0).addRow(2, null, // Should NOT match left null (SQL standard)
    2.0).addRow(3, "Cc", // Should NOT match left null (SQL standard)
    null).addRow(5, "Ee", // No match in left
    5.0).buildWithEos();
    DataSchema resultSchema = new DataSchema(new String[] { "int_col1", "string_col1", "double_col1", "int_col2", "string_col2", "double_col2" }, new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.STRING, ColumnDataType.DOUBLE, ColumnDataType.INT, ColumnDataType.STRING, ColumnDataType.DOUBLE });
    // Composite key join on columns 1 and 2 (string_col and double_col)
    HashJoinOperator operator = getOperator(compositeSchema, resultSchema, JoinRelType.LEFT, List.of(1, 2), List.of(1, 2), List.of(), PlanNode.NodeHint.EMPTY);
    List<Object[]> resultRows = ((MseBlock.Data) operator.nextBlock()).asRowHeap().getRows();
    // Expected behavior per SQL standard:
    // - Row 1: (1, "Aa", 1.0) should match (1, "Aa", 1.0)
    // - Row 2: (2, null, 2.0) should NOT match (2, null, 2.0) -> left preserved with nulls
    // - Row 3: (3, "Cc", null) should NOT match (3, "Cc", null) -> left preserved with nulls
    // - Row 4: (4, "Dd", 4.0) has no match -> left preserved with nulls
    assertEquals(resultRows.size(), 4);
    // Match
    assertEquals(resultRows.get(0), new Object[] { 1, "Aa", 1.0, 1, "Aa", 1.0 });
    // Left null preserved
    assertEquals(resultRows.get(1), new Object[] { 2, null, 2.0, null, null, null });
    // Left null preserved
    assertEquals(resultRows.get(2), new Object[] { 3, "Cc", null, null, null, null });
    // Left unmatched preserved
    assertEquals(resultRows.get(3), new Object[] { 4, "Dd", 4.0, null, null, null });
}

