@Test
public void shouldHandleCrossJoin() {
    DataSchema leftSchema = new DataSchema(new String[] { "int_col", "string_col" }, new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.STRING });
    DataSchema rightSchema = new DataSchema(new String[] { "int_col", "string_col" }, new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.STRING });
    when(_leftInput.nextBlock()).thenReturn(OperatorTestUtil.block(leftSchema, new Object[] { 1, "Aa" }, new Object[] { 2, "BB" })).thenReturn(SuccessMseBlock.INSTANCE);
    when(_rightInput.nextBlock()).thenReturn(OperatorTestUtil.block(rightSchema, new Object[] { 2, "Aa" }, new Object[] { 2, "BB" }, new Object[] { 3, "BB" })).thenReturn(SuccessMseBlock.INSTANCE);
    DataSchema resultSchema = new DataSchema(new String[] { "int_col1", "string_col1", "int_col2", "string_col2" }, new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.STRING, ColumnDataType.INT, ColumnDataType.STRING });
    NonEquiJoinOperator operator = getOperator(leftSchema, resultSchema, JoinRelType.INNER, List.of());
    List<Object[]> resultRows = ((MseBlock.Data) operator.nextBlock()).asRowHeap().getRows();
    assertEquals(resultRows.size(), 6);
    assertEquals(resultRows.get(0), new Object[] { 1, "Aa", 2, "Aa" });
    assertEquals(resultRows.get(1), new Object[] { 1, "Aa", 2, "BB" });
    assertEquals(resultRows.get(2), new Object[] { 1, "Aa", 3, "BB" });
    assertEquals(resultRows.get(3), new Object[] { 2, "BB", 2, "Aa" });
    assertEquals(resultRows.get(4), new Object[] { 2, "BB", 2, "BB" });
    assertEquals(resultRows.get(5), new Object[] { 2, "BB", 3, "BB" });
}

