    Assert.assertEquals(uniqueValues.length, 2);
    // Dict ID 1
    Assert.assertEquals(uniqueValues[0], Long.valueOf(200L));
    // Dict ID 2
    Assert.assertEquals(uniqueValues[1], Long.valueOf(300L));
}

