    FieldConfig col1Cfg = JsonUtils.stringToObject(col1CfgStr, FieldConfig.class);
    String col2CfgStr = "{" + "  \"name\": \"col2\"," + "  \"indexes\": {" + "    \"bloom\": {\"enabled\": \"true\"}" + "  }," + "  \"tierOverwrites\": {" + "    \"coldTier\": {" + "      \"encodingType\": \"RAW\"," + "      \"indexes\": {}" + "    }" + "  }" + "}";
    FieldConfig col2Cfg = JsonUtils.stringToObject(col2CfgStr, FieldConfig.class);
    String stIdxCfgStr = "{" + "  \"dimensionsSplitOrder\": [\"col1\"]," + "  \"functionColumnPairs\": [\"MAX__col1\"]," + "  \"maxLeafRecords\": 10" + "}";
