    TableConfig tableConfig = new TableConfigBuilder(TableType.OFFLINE).setTableName(TABLE_NAME).setStarTreeIndexConfigs(Collections.singletonList(stIdxCfg)).setTierOverwrites(JsonUtils.stringToJsonNode("{\"coldTier\": {\"starTreeIndexConfigs\": []}}")).setFieldConfigList(Arrays.asList(col1Cfg, col2Cfg)).build();
