private static ImmutableSegmentImpl mockImmutableSegment(int sequenceNumber, ThreadSafeMutableRoaringBitmap validDocIds, @Nullable ThreadSafeMutableRoaringBitmap queryableDocIds, @Nullable List<PrimaryKey> primaryKeys) {
