private void verifyAddReplaceRemoveSegmentWithRecordDelete(HashFunction hashFunction) throws IOException {
    ConcurrentMapPartitionUpsertMetadataManagerForConsistentDeletes upsertMetadataManager = new ConcurrentMapPartitionUpsertMetadataManagerForConsistentDeletes(REALTIME_TABLE_NAME, 0, _contextBuilder.setHashFunction(hashFunction).build());
    Map<Object, ConcurrentMapPartitionUpsertMetadataManagerForConsistentDeletes.RecordLocation> recordLocationMap = upsertMetadataManager._primaryKeyToRecordLocationMap;
