    List<RecordInfo> recordInfoList2;
    // get recordInfo from validDocIdSnapshot.
    // segment2 snapshot: 0 -> {0, 100}, 2 -> {2, 120}, 3 -> {3, 80}
    // segment1 snapshot: 1 -> {4, 120}
