@Test
public void testValidateUpsertConfig() {
    Schema schema = new Schema.SchemaBuilder().setSchemaName(TABLE_NAME).addSingleValueDimension("myCol", FieldSpec.DataType.STRING).addDateTime(TIME_COLUMN, FieldSpec.DataType.LONG, "1:MILLISECONDS:EPOCH", "1:MILLISECONDS").build();
    UpsertConfig upsertConfig = new UpsertConfig(UpsertConfig.Mode.FULL);
    TableConfig tableConfig = new TableConfigBuilder(TableType.OFFLINE).setTableName(TABLE_NAME).setUpsertConfig(upsertConfig).setTimeColumnName(TIME_COLUMN).build();
    try {
        TableConfigUtils.validateUpsertAndDedupConfig(tableConfig, schema);
        fail();
    } catch (IllegalStateException e) {
        assertEquals(e.getMessage(), "Upsert/Dedup table is for realtime table only.");
    }
    tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(TABLE_NAME).setUpsertConfig(upsertConfig).build();
    try {
        TableConfigUtils.validateUpsertAndDedupConfig(tableConfig, schema);
        fail();
    } catch (IllegalStateException e) {
        assertEquals(e.getMessage(), "Upsert/Dedup table must have primary key columns in the schema");
    }
    schema = new Schema.SchemaBuilder().setSchemaName(TABLE_NAME).addSingleValueDimension("myCol", FieldSpec.DataType.STRING).setPrimaryKeyColumns(Lists.newArrayList("myCol")).build();
    Map<String, String> streamConfigs = getStreamConfigs();
    tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(TABLE_NAME).setUpsertConfig(upsertConfig).setStreamConfigs(streamConfigs).build();
    try {
        TableConfigUtils.validateUpsertAndDedupConfig(tableConfig, schema);
        fail();
    } catch (IllegalStateException e) {
        assertEquals(e.getMessage(), "Upsert/Dedup table must use strict replica-group (i.e. strictReplicaGroup) based routing");
    }
    // invalid tag override with upsert
    tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(TABLE_NAME).setTimeColumnName(TIME_COLUMN).setUpsertConfig(new UpsertConfig(UpsertConfig.Mode.FULL)).setStreamConfigs(getStreamConfigs()).setRoutingConfig(new RoutingConfig(null, null, RoutingConfig.STRICT_REPLICA_GROUP_INSTANCE_SELECTOR_TYPE, false)).setTagOverrideConfig(new TagOverrideConfig("T1_REALTIME", "T2_REALTIME")).build();
    try {
        TableConfigUtils.validateUpsertAndDedupConfig(tableConfig, schema);
        fail("Tag override must not be allowed with upsert");
    } catch (IllegalStateException e) {
        assertEquals(e.getMessage(), "Invalid tenant tag override used for Upsert/Dedup table");
    }
    // tag override even with same tag for CONSUMING and COMPLETED with upsert should fail
    tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(TABLE_NAME).setTimeColumnName(TIME_COLUMN).setUpsertConfig(new UpsertConfig(UpsertConfig.Mode.FULL)).setStreamConfigs(getStreamConfigs()).setRoutingConfig(new RoutingConfig(null, null, RoutingConfig.STRICT_REPLICA_GROUP_INSTANCE_SELECTOR_TYPE, false)).setTagOverrideConfig(new TagOverrideConfig("T1_REALTIME", "T1_REALTIME")).build();
    try {
        TableConfigUtils.validateUpsertAndDedupConfig(tableConfig, schema);
        fail("Tag override must not be allowed with upsert");
    } catch (IllegalStateException e) {
        assertEquals(e.getMessage(), "Invalid tenant tag override used for Upsert/Dedup table");
    }
    // Instance assignment config with just CONSUMING instance partitions configured should be allowed
    InstanceAssignmentConfig instanceAssignmentConfig = Mockito.mock(InstanceAssignmentConfig.class);
    tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(TABLE_NAME).setTimeColumnName(TIME_COLUMN).setUpsertConfig(new UpsertConfig(UpsertConfig.Mode.FULL)).setStreamConfigs(getStreamConfigs()).setRoutingConfig(new RoutingConfig(null, null, RoutingConfig.STRICT_REPLICA_GROUP_INSTANCE_SELECTOR_TYPE, false)).setInstanceAssignmentConfigMap(Map.of(InstancePartitionsType.CONSUMING.name(), instanceAssignmentConfig)).build();
    TableConfigUtils.validateUpsertAndDedupConfig(tableConfig, schema);
    // Instance assignment config with CONSUMING and COMPLETED instance partitions configured should not be allowed
    tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(TABLE_NAME).setTimeColumnName(TIME_COLUMN).setUpsertConfig(new UpsertConfig(UpsertConfig.Mode.FULL)).setStreamConfigs(getStreamConfigs()).setRoutingConfig(new RoutingConfig(null, null, RoutingConfig.STRICT_REPLICA_GROUP_INSTANCE_SELECTOR_TYPE, false)).setInstanceAssignmentConfigMap(Map.of(InstancePartitionsType.CONSUMING.name(), instanceAssignmentConfig, InstancePartitionsType.COMPLETED.name(), instanceAssignmentConfig)).build();
    try {
        TableConfigUtils.validateUpsertAndDedupConfig(tableConfig, schema);
        fail("Instance assignment config with COMPLETED instance partitions must not be allowed with upsert");
    } catch (IllegalStateException e) {
        assertEquals(e.getMessage(), "COMPLETED instance partitions can't be configured for upsert / dedup tables");
    }
    // empty tag override with upsert should pass
    tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(TABLE_NAME).setTimeColumnName(TIME_COLUMN).setUpsertConfig(new UpsertConfig(UpsertConfig.Mode.FULL)).setStreamConfigs(getStreamConfigs()).setRoutingConfig(new RoutingConfig(null, null, RoutingConfig.STRICT_REPLICA_GROUP_INSTANCE_SELECTOR_TYPE, false)).setTagOverrideConfig(new TagOverrideConfig(null, null)).build();
    TableConfigUtils.validateUpsertAndDedupConfig(tableConfig, schema);
    tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(TABLE_NAME).setUpsertConfig(upsertConfig).setRoutingConfig(new RoutingConfig(null, null, RoutingConfig.STRICT_REPLICA_GROUP_INSTANCE_SELECTOR_TYPE, false)).setStreamConfigs(streamConfigs).build();
    TableConfigUtils.validateUpsertAndDedupConfig(tableConfig, schema);
    StarTreeIndexConfig starTreeIndexConfig = new StarTreeIndexConfig(Lists.newArrayList("myCol"), null, Collections.singletonList(new AggregationFunctionColumnPair(AggregationFunctionType.COUNT, "myCol").toColumnName()), null, 10);
    tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(TABLE_NAME).setUpsertConfig(upsertConfig).setRoutingConfig(new RoutingConfig(null, null, RoutingConfig.STRICT_REPLICA_GROUP_INSTANCE_SELECTOR_TYPE, false)).setStarTreeIndexConfigs(Lists.newArrayList(starTreeIndexConfig)).setStreamConfigs(streamConfigs).build();
    try {
        TableConfigUtils.validateUpsertAndDedupConfig(tableConfig, schema);
        fail();
    } catch (IllegalStateException e) {
        assertEquals(e.getMessage(), "The upsert table cannot have star-tree index.");
    }
    //With Aggregate Metrics
    tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(TABLE_NAME).setUpsertConfig(upsertConfig).setRoutingConfig(new RoutingConfig(null, null, RoutingConfig.STRICT_REPLICA_GROUP_INSTANCE_SELECTOR_TYPE, false)).setStreamConfigs(streamConfigs).setAggregateMetrics(true).build();
    try {
        TableConfigUtils.validateUpsertAndDedupConfig(tableConfig, schema);
        fail();
    } catch (IllegalStateException e) {
        assertEquals(e.getMessage(), "Metrics aggregation and upsert cannot be enabled together");
    }
    //With aggregation Configs in Ingestion Config
    IngestionConfig ingestionConfig = new IngestionConfig();
    ingestionConfig.setAggregationConfigs(Collections.singletonList(new AggregationConfig("twiceSum", "SUM(twice)")));
    tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(TABLE_NAME).setUpsertConfig(upsertConfig).setRoutingConfig(new RoutingConfig(null, null, RoutingConfig.STRICT_REPLICA_GROUP_INSTANCE_SELECTOR_TYPE, false)).setStreamConfigs(streamConfigs).setIngestionConfig(ingestionConfig).build();
    try {
        TableConfigUtils.validateUpsertAndDedupConfig(tableConfig, schema);
        fail();
    } catch (IllegalStateException e) {
        assertEquals(e.getMessage(), "Metrics aggregation and upsert cannot be enabled together");
    }
    //With aggregation Configs in Ingestion Config and IndexingConfig at the same time
    tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(TABLE_NAME).setUpsertConfig(upsertConfig).setRoutingConfig(new RoutingConfig(null, null, RoutingConfig.STRICT_REPLICA_GROUP_INSTANCE_SELECTOR_TYPE, false)).setStreamConfigs(streamConfigs).setAggregateMetrics(true).setIngestionConfig(ingestionConfig).build();
    try {
        TableConfigUtils.validateUpsertAndDedupConfig(tableConfig, schema);
        fail();
    } catch (IllegalStateException e) {
        assertEquals(e.getMessage(), "Metrics aggregation cannot be enabled in the Indexing Config and Ingestion Config at the same time");
    }
